#include "camera.h"
#include <tlhelp32.h>
#include <bcrypt.h>
#include <vector>
#include <string>
#include <cstdio>
#include <stdexcept>
#include <cmath>
namespace {
DWORD pid;Status* s;
void check(bool b,const char* msg){if(!b)throw std::runtime_error(msg);}
void find(){HANDLE snap=CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS,0);PROCESSENTRY32W e{sizeof e};int count=0;if(Process32FirstW(snap,&e))do{if(!_wcsicmp(e.szExeFile,L"Dishonored2.exe")){pid=e.th32ProcessID;++count;}}while(Process32NextW(snap,&e));CloseHandle(snap);check(count==1,"Start one Dishonored2.exe instance.");}
bool connect(){wchar_t name[80];swprintf_s(name,L"Local\\VoidCamera_%lu",pid);HANDLE h=OpenFileMappingW(FILE_MAP_ALL_ACCESS,FALSE,name);if(!h)return false;s=(Status*)MapViewOfFile(h,FILE_MAP_ALL_ACCESS,0,0,sizeof(Status));CloseHandle(h);return s&&s->magic==0x56433031;}
void verify(HANDLE p){wchar_t path[32768];DWORD len=32768;check(QueryFullProcessImageNameW(p,0,path,&len),"Cannot read game path.");HANDLE f=CreateFileW(path,GENERIC_READ,FILE_SHARE_READ|FILE_SHARE_WRITE,nullptr,OPEN_EXISTING,0,nullptr);check(f!=INVALID_HANDLE_VALUE,"Cannot read executable.");BCRYPT_ALG_HANDLE a{};BCRYPT_HASH_HANDLE h{};check(BCryptOpenAlgorithmProvider(&a,BCRYPT_SHA256_ALGORITHM,nullptr,0)>=0,"SHA256 unavailable.");DWORD n=0,done=0;BCryptGetProperty(a,BCRYPT_OBJECT_LENGTH,(PUCHAR)&n,4,&done,0);std::vector<BYTE> obj(n),buf(65536);check(BCryptCreateHash(a,&h,obj.data(),n,nullptr,0,0)>=0,"SHA256 initialization failed.");bool ok=true;while(ReadFile(f,buf.data(),DWORD(buf.size()),&done,nullptr)&&done){if(BCryptHashData(h,buf.data(),done,0)<0){ok=false;break;}}BYTE digest[32];ok=ok&&BCryptFinishHash(h,digest,32,0)>=0;BCryptDestroyHash(h);BCryptCloseAlgorithmProvider(a,0);CloseHandle(f);char hex[65]{};for(int i=0;i<32;++i)sprintf(hex+2*i,"%02x",digest[i]);check(ok&&!strcmp(hex,"b671f8249422862bf557d00aab2f4bb671ed4515cc10ad8a8a9decad84516180"),"Unsupported Dishonored 2 executable.");}
void inject(){HANDLE p=OpenProcess(PROCESS_CREATE_THREAD|PROCESS_QUERY_INFORMATION|PROCESS_VM_OPERATION|PROCESS_VM_WRITE|PROCESS_VM_READ,FALSE,pid);check(p!=nullptr,"Cannot open game process.");verify(p);
 wchar_t path[32768];GetModuleFileNameW(nullptr,path,32768);std::wstring dll=path;dll=dll.substr(0,dll.find_last_of(L"\\/")+1)+L"VoidCamera.dll";check(GetFileAttributesW(dll.c_str())!=INVALID_FILE_ATTRIBUTES,"Keep VoidCamera.dll beside the injector.");size_t n=(dll.size()+1)*2;void* remote=VirtualAllocEx(p,nullptr,n,MEM_COMMIT|MEM_RESERVE,PAGE_READWRITE);SIZE_T done=0;check(remote&&WriteProcessMemory(p,remote,dll.c_str(),n,&done)&&done==n,"Cannot publish DLL path.");
 // Resolve the loader in the target module, rather than assuming equal ASLR bases.
 auto local=GetModuleHandleW(L"kernel32.dll");auto loader=GetProcAddress(local,"LoadLibraryW");HMODULE owner{};GetModuleHandleExW(GET_MODULE_HANDLE_EX_FLAG_FROM_ADDRESS|GET_MODULE_HANDLE_EX_FLAG_UNCHANGED_REFCOUNT,(LPCWSTR)loader,&owner);wchar_t module[32768];GetModuleFileNameW(owner,module,32768);auto name=wcsrchr(module,L'\\');name=name?name+1:module;
 uintptr_t remoteBase=0;HANDLE snap=CreateToolhelp32Snapshot(TH32CS_SNAPMODULE,pid);MODULEENTRY32W m{sizeof m};if(Module32FirstW(snap,&m))do{if(!_wcsicmp(m.szModule,name))remoteBase=(uintptr_t)m.modBaseAddr;}while(Module32NextW(snap,&m));CloseHandle(snap);check(remoteBase!=0,"Loader module not found.");auto entry=(LPTHREAD_START_ROUTINE)(remoteBase+(uintptr_t)loader-(uintptr_t)owner);HANDLE t=CreateRemoteThread(p,nullptr,0,entry,remote,0,nullptr);check(t!=nullptr,"DLL injection failed.");DWORD wait=WaitForSingleObject(t,10000);CloseHandle(t);if(wait==WAIT_OBJECT_0)VirtualFreeEx(p,remote,0,MEM_RELEASE);CloseHandle(p);check(wait==WAIT_OBJECT_0,"DLL load timed out.");for(int i=0;i<250;++i){if(!s)connect();if(s&&s->error)throw std::runtime_error("DLL initialization error "+std::to_string(s->error)+" (1: version or occupied camera hook).");if(s&&s->ready)return;Sleep(20);}throw std::runtime_error("DLL did not initialize.");}
void command(LONG action){InterlockedExchange(&s->command,0);for(int i=0;i<250&&s->ack;i++)Sleep(8);check(!s->ack,"Command reset timed out.");InterlockedExchange(&s->command,action);for(int i=0;i<250&&s->ack!=action;i++)Sleep(8);check(s->ack==action,"Command timed out.");}
void print(){printf("ready=%ld error=%ld enabled=%ld overlay=%ld timeStopReady=%ld timeStopped=%ld HUD=%ld/%ld focusLoss=%ld/%ld view=%llX captures=%u applied=%u cached=%u\nXYZ %.5f %.5f %.5f | PYR %.3f %.3f %.3f | Aspect %.4f | FOV H %.3f V %.3f | speed %.3f\n",s->ready,s->error,s->enabled,s->overlay,s->timeStopReady,s->timeStopped,s->hudReady,s->hudHidden,s->focusLossReady,s->focusLossEnabled,s->view,s->captures,s->applied,s->cached,s->pose.xyz[0],s->pose.xyz[1],s->pose.xyz[2],s->pose.pyr[0],s->pose.pyr[1],s->pose.pyr[2],s->aspect,s->horizontalFov,s->pose.fov,s->pose.speed);}
}
int wmain(int argc,wchar_t** argv){try{find();bool connected=connect();if(argc==1||!wcscmp(argv[1],L"--inject")){if(!connected)inject();print();return s->error?1:0;}check(connected,"Camera is not injected.");if(!wcscmp(argv[1],L"--status")){print();return 0;}check(s->ready&&!s->error,"Camera initialization failed.");if(!wcscmp(argv[1],L"--on"))command(1);else if(!wcscmp(argv[1],L"--off"))command(2);else if(!wcscmp(argv[1],L"--overlay"))command(4);else if(!wcscmp(argv[1],L"--pause"))command(5);else if(!wcscmp(argv[1],L"--resume"))command(6);else if(!wcscmp(argv[1],L"--pose")&&argc==10){for(int i=0;i<8;++i){wchar_t* end=nullptr;float v=wcstof(argv[i+2],&end);check(end&&!*end&&std::isfinite(v),"Invalid numeric value.");s->args[i]=v;}MemoryBarrier();command(3);}else throw std::runtime_error("Use --inject, --status, --on, --off, --overlay, --pause, --resume or --pose X Y Z P Y R FOV SPEED.");print();return 0;}catch(const std::exception& e){fprintf(stderr,"%s\n",e.what());return 1;}}
